// Official FAW-VW photos per model (vetted: no Chinese text), generated by
// scripts/process-official-photos.mjs into /public/images/models/<slug>/photo-<n>.webp.
export interface Photo {
  src: string
  alt: string
  kind: 'exterior' | 'interior'
}

export interface ModelMedia {
  // Full-screen hero background. Omitted → studio-photo hero on a dark backdrop.
  hero?: Photo
  // One photo per highlight (same order as modelDetails.highlights); undefined → studio photo.
  features: (Photo | undefined)[]
  gallery: Photo[]
}

const p = (slug: string, n: number, alt: string, kind: Photo['kind'] = 'exterior'): Photo => ({
  src: `/images/models/${slug}/photo-${n}.webp`,
  alt,
  kind,
})

